// Generated by vibelang from src/features/runs/summary.ts; the migrate flow writes it again with each batch.
import { listed } from "./contract";
import { hasDomainOutcome } from "./todoRun";
/** The `fraction` percentile of `values` by nearest rank, or `null` for none. */
export const percentile = (values, fraction) => {
    if (values.length === 0)
        return null;
    const sorted = [...values].sort((left, right) => left - right);
    return sorted[Math.min(sorted.length, Math.max(1, Math.ceil(fraction * sorted.length))) - 1];
};
/** Every listed flow of `runs`, the most runs first, then by name. Acts on runs (`run/*`) aren't listed. */
export const flowSummary = (runs) => {
    const byFlow = new Map();
    for (const run of runs) {
        if (!listed(run.flow))
            continue;
        const group = byFlow.get(run.flow);
        if (group === undefined)
            byFlow.set(run.flow, [run]);
        else
            group.push(run);
    }
    return [...byFlow].map(([flow, group]) => {
        const ended = group.filter((run) => (run.status === "completed" || run.status === "failed" || run.status === "cancelled") && run.finishedAtMs !== null);
        const unknown = ended.some((run) => hasDomainOutcome(run.flow) && run.status === "completed" &&
            (run.outcome === undefined || run.outcome === "unknown"));
        const succeeded = ended.filter((run) => run.status === "completed" &&
            (!hasDomainOutcome(run.flow) || run.outcome === "succeeded")).length;
        return {
            flow,
            runs: group.length,
            settled: ended.length,
            succeeded,
            successRate: ended.length === 0 || unknown ? null : succeeded / ended.length,
            p95Ms: percentile(ended.map((run) => run.finishedAtMs - run.createdAtMs), 0.95),
        };
    }).sort((left, right) => right.runs - left.runs || left.flow.localeCompare(right.flow));
};
